import "server-only";
import { del, get, put } from "@vercel/blob";
import type { FileStorage } from "./index";

/** Keys are generated by the app: 32 hex characters plus an extension. */
const KEY_PATTERN = /^[a-f0-9]{32}\.[a-z0-9]{2,5}$/;

/**
 * Stores files in a *private* Vercel Blob store.
 *
 * Used when STORAGE_DRIVER=vercel-blob. Nothing else in the app changes:
 * browsers still reach files only through /api/files/[id], which runs the
 * permission check and then asks this class for the bytes. The blob store's
 * own URLs are never exposed and, being private, would not work anyway.
 *
 * Authentication: on Vercel the SDK uses the project's OIDC token
 * automatically once the store is connected to the project (which also sets
 * BLOB_STORE_ID). Elsewhere, set BLOB_READ_WRITE_TOKEN.
 */
export class VercelBlobStorage implements FileStorage {
  private readonly prefix: string;

  constructor(prefix = "uploads") {
    this.prefix = prefix.replace(/^\/+|\/+$/g, "");
  }

  private pathFor(key: string): string {
    if (!KEY_PATTERN.test(key)) throw new Error("Invalid storage key.");
    return `${this.prefix}/${key}`;
  }

  async put(key: string, data: Buffer): Promise<void> {
    await put(this.pathFor(key), data, {
      access: "private",
      // The key is already random and unique; keep it exactly as given.
      addRandomSuffix: false,
      allowOverwrite: false,
    });
  }

  async get(key: string): Promise<Buffer | null> {
    const result = await get(this.pathFor(key), { access: "private" });
    if (!result || result.statusCode !== 200) return null;
    return Buffer.from(await new Response(result.stream).arrayBuffer());
  }

  async delete(key: string): Promise<void> {
    await del(this.pathFor(key));
  }
}
